!function(){var a=document.getElementById("accordion");fetch("http://localhost:4000/api/public/faqs").then(function(a){return a.json()}).then(function(o){var n=o.faqs||[];0!==n.length?a.innerHTML=n.map(function(a,o){var n=o+1;return'<div class="accordion-item wow fadeInUp">  <h2 class="accordion-header" id="heading'+n+'">    <button class="accordion-button'+(0===o?"":" collapsed")+'" type="button" data-bs-toggle="collapse" data-bs-target="#collapse'+n+'" aria-expanded="'+(0===o?"true":"false")+'" aria-controls="collapse'+n+'">'+a.question+'    </button>  </h2>  <div id="collapse'+n+'" class="accordion-collapse collapse'+(0===o?" show":"")+'" role="region" aria-labelledby="heading'+n+'" data-bs-parent="#accordion">    <div class="accordion-body"><p>'+a.answer+"</p></div>  </div></div>"}).join(""):a.innerHTML="<p>No FAQs available right now.</p>"}).catch(function(o){a.innerHTML="<p>Could not load FAQs ("+o.message+").</p>"})}();